// lib/shard/src/count.rs line 11-25
pub struct CountRequestInternal {
    pub filter: Option<Filter>,
    /// If true, count exact number of points. If false, count approximate number of points faster.
    /// Approximate count might be unreliable during the indexing process. Default: true
    #[serde(default = "CountRequestInternal::default_exact")]
    pub exact: bool,
}

impl CountRequestInternal {
    pub const fn default_exact() -> bool { true }
}

// src/actix/api/count_api.rs line 16-70 (count API handler)
#[post("/collections/{collection_name}/points/count")]
async fn count_points(...) -> impl Responder {
    let CountRequest { count_request, shard_key } = request.into_inner();
    let result = do_count_points(
        dispatcher.toc(&auth, &pass),
        &collection.collection_name,
        count_request,  // CountRequestInternal with exact field
        params.consistency,
        params.timeout(),
        shard_selector,
        auth,
        request_hw_counter.get_counter(),
    ).await;
    helpers::process_response(result, timing, ...)
}
